S('wahl','w_risiko',lv=>{const list=shuffle(RISK).slice(0,5),n=list.filter(r=>r[1]).length;return task('Fünf Personen am Stammtisch prahlen mit ihren Firmen:<ol>'+list.map(r=>'<li>'+r[0]+'</li>').join('')+'</ol>','Wie viele dieser Personen haften für Schulden ihrer Firma unbeschränkt mit ihrem Privatvermögen?','Zähle nur die Leute, bei denen der Gerichtsvollzieher auch privat vorbeikommen darf.',n,`Unbeschränkt privat haften: ${list.filter(r=>r[1]).map(r=>r[0]).join(', ')||'niemand'}. Das sind <b>${n}</b>. Wer nur seine (bezahlte) Einlage riskiert, haftet nicht privat.`,'Personen',0);});
const F_TRUE=['Ein Handelsunternehmen gehört zum tertiären Sektor, obwohl es körperliche Waren verkauft.','Eine GmbH bleibt eine Kapitalgesellschaft, auch wenn sie nur einen Gesellschafter hat.','Stehen vielen Anbietern nur ein einziger Nachfrager gegenüber, liegt ein Nachfragemonopol vor.','Auch eine GmbH kann gemeinnützig sein und dann „gGmbH“ heißen.','Für Steuervorteile sind Satzung und tatsächliche Geschäftsführung wichtig.','Eine AG kann von einer einzigen Person gegründet werden.'];
const F_FALSE=['Ein Softwareunternehmen gehört zwingend zum sekundären Sektor.','Jede eingetragene Personengesellschaft wird automatisch zur Kapitalgesellschaft.','Die Bezeichnung „e.V.“ reicht allein als Nachweis der Gemeinnützigkeit.','Ein neues Verkaufsgebiet erweitert automatisch die Produktpalette.','Ein Kommanditist haftet niemals persönlich.','Eine AG ist nur dann eine Kapitalgesellschaft, wenn ihre Aktien an der Börse gehandelt werden.','Gemeinnützige Organisationen dürfen keinerlei Einnahmen erzielen.','Eine GmbH muss immer mindestens zwei Gesellschafter haben.'];
S('wahl','w_falle',lv=>{const r=pick(F_TRUE);return choice('Prüfungsaufgabe: Genau eine der folgenden Aussagen ist richtig. Die anderen enthalten einen wahren Kern, kippen aber an einem einzigen Wort.','Welche Aussage ist richtig?','Suche Alarmwörter wie „zwingend“, „automatisch“, „allein“, „niemals“, „nur“ und „immer“.',r,shuffle(F_FALSE),`Richtig: <b>${r}</b> Die anderen Aussagen scheitern an Wörtern wie „zwingend“, „automatisch“, „allein“, „niemals“, „nur“ oder „immer“.`);});
const OLD=['Eine AG braucht mindestens fünf Gründer.','In der OHG erhält jeder Gesellschafter ohne Vertrag zuerst 4 % auf seine Einlage, der Rest wird nach Köpfen verteilt.','Eine GbR ist grundsätzlich nicht rechtsfähig.','Eine KGaA braucht mindestens fünf Gründer.'];
const CUR=['Eine AG kann von einer Person gegründet werden.','Die GmbH braucht 25.000 € Stammkapital.','Eine UG muss ein Viertel ihres Jahresüberschusses in eine Rücklage stellen.','In der OHG darf ohne andere Regel jeder Gesellschafter allein vertreten.','Kommanditisten sind von der Geschäftsführung ausgeschlossen.','In der eG hat jedes Mitglied grundsätzlich eine Stimme.'];
S('wahl','w_alt',lv=>{const r=pick(OLD);return choice('Kai lernt mit einem alten Lehrbuch aus dem Keller seiner Eltern. Einige Regeln darin gelten heute nicht mehr.','Welche Aussage ist veraltet und gilt heute nicht mehr?','Drei Aussagen gelten noch. Eine stammt aus einer Zeit vor einer Gesetzesänderung.',r,shuffle(CUR),`Veraltet: <b>${r}</b> ${r.includes('fünf')?'Seit 1994 reicht bei der AG eine Person (§ 2 AktG). § 280 AktG nennt auch für die KGaA keine Mindestzahl.':r.includes('4 %')?'Seit dem 1. Januar 2024 gilt § 709 Abs. 3 BGB: Beteiligungsverhältnisse, sonst Beitragswerte, sonst gleiche Anteile.':'Seit 2024 ist eine GbR rechtsfähig, wenn sie am Rechtsverkehr teilnehmen soll (§ 705 Abs. 2 BGB).'}`);});
const EV=[
 ['Der „Förderverein Digitale Bildung e.V.“ steht im Vereinsregister. Weitere Angaben fehlen.','Welche Aussage lässt sich allein daraus sicher ableiten?','Er ist eingetragen und als nicht wirtschaftlicher Verein rechtsfähig.',['Er ist steuerlich gemeinnützig.','Spenden an ihn sind in jedem Fall steuerlich abzugsfähig.','Er darf keine Einnahmen erzielen.','Er ist eine Kapitalgesellschaft.'],'Aus dem Eintrag folgt nur: eingetragen und rechtsfähig (§ 21 BGB). Gemeinnützigkeit entscheidet das Finanzamt.'],
 ['Die „Retter der Diskette gGmbH“ verfolgt laut Satzung ausschließlich und unmittelbar steuerbegünstigte Bildungszwecke.','Welche Aussage ist richtig?','Sie darf keine Gewinne an die Gesellschafter ausschütten.',['Sie darf keinerlei Einnahmen erzielen.','Sie ist wegen des „g“ eine Behörde.','Sie ist keine GmbH, sondern ein Verein.','Ihre Gesellschafter haften unbeschränkt.'],'Gemeinnützige Körperschaften dürfen Einnahmen erzielen, Mittel aber nur für den Zweck verwenden. Keine Gewinnausschüttung an Gesellschafter (§ 55 AO).'],
 ['Die „Sozialwerk Sonnenschein GmbH“ wirbt groß mit „sozialem Engagement“. Zur Anerkennung durch das Finanzamt enthält der Fall nichts.','Was lässt sich sicher sagen?','Ob sie gemeinnützig ist, lässt sich aus den Angaben nicht erkennen.',['Sie ist gemeinnützig, weil sie sozial wirbt.','Sie muss „gGmbH“ heißen.','Sie ist eine Behörde.','Sie ist eine Personengesellschaft.'],'Werbung ist keine Anerkennung. Ohne Angaben zu Zweck und Anerkennung bleibt es offen.']
];
S('wahl','w_ev',lv=>{const [sc,q,r,w,why]=pick(EV);return choice(sc,q,'Was steht wirklich im Fall, und was wäre nur geraten?',r,w,`Richtig: <b>${r}</b> ${why}`);});

function genTask(cat,lv=2,recent,subId){
 // Public contract accepts genTask(subId, level); A1 engine also uses the four-argument form.
 if(SUBS.some(s=>s.id===cat)){subId=cat;cat=null;}
 if(cat==='mix'||cat==='all')cat=pick(CATS)[0];
 const pool=SUBS.filter(s=>subId?s.id===subId:s.cat===cat);
 if(!pool.length)throw new Error('Unknown W4 task: '+(subId||cat));
 let t,s;
 for(let i=0;i<20;i++){s=pick(pool);t=s.f(lv);if(!recent||!recent.includes(t.key))break;}
 return {...t,cat:s.cat,sub:s.id,subLabel:s.label};
}
